    ['javier', 'javier-m3', 'entre 2000 y 3000', 'declared_monthly_income', { min: 2000, max: 3000 }, 'participant'],
    ['rosa', 'rosa-m1', 'Ahorros no tenemos', 'available_savings', 0, 'buying_unit'],
